create or replace package body sales_report as
  function quarter_total(p_region in varchar2, p_year in number, p_quarter in number) return number is
    l_total number;
  begin
    select nvl(sum(total), 0)
      into l_total
      from quarterly_sales_v
     where region = p_region and fiscal_year = p_year and fiscal_quarter = p_quarter;
    return l_total;
  end quarter_total;
end sales_report;
/
create or replace package body fiscal_calendar as
  function year_of(p_date in date) return number is
  begin
    return extract(year from p_date) + case when extract(month from p_date) >= 7 then 1 else 0 end;
  end year_of;

  function quarter_of(p_date in date) return number is
  begin
    -- Fiscal year starts July (Month 7).
    -- Q1: Jul, Aug, Sep (Months 7, 8, 9)
    -- Q2: Oct, Nov, Dec (Months 10, 11, 12)
    -- Q3: Jan, Feb, Mar (Months 1, 2, 3)
    -- Q4: Apr, May, Jun (Months 4, 5, 6)

    -- Map calendar month (1-12) to fiscal quarter (1-4)
    -- Months 7, 8, 9 -> Q1
    -- Months 10, 11, 12 -> Q2
    -- Months 1, 2, 3 -> Q3
    -- Months 4, 5, 6 -> Q4

    case extract(month from p_date)
      when 7 then return 1;
      when 8 then return 1;
      when 9 then return 1;
      when 10 then return 2;
      when 11 then return 2;
      when 12 then return 2;
      when 1 then return 3;
      when 2 then return 3;
      when 3 then return 3;
      when 4 then return 4;
      when 5 then return 4;
      when 6 then return 4;
    end case;
  end quarter_of;
end fiscal_calendar;
/
